from pathlib import Path
from PIL import Image
import html, json, re, csv
from data import PRODUCTS, WIRE
ROOT=Path(__file__).resolve().parent.parent; SITE=ROOT/'site'; IMG=SITE/'assets/img'
IMG.mkdir(parents=True,exist_ok=True)
(SITE/'assets/logo.png').write_bytes((ROOT/'src/logo.png').read_bytes())
for p in IMG.iterdir(): p.unlink()
def image(path, alt, eager=False):
    source=ROOT/'reference/img/images'/path
    stem=path.replace('/','-').lower().replace(' ','-').rsplit('.',1)[0]; t=ROOT/'src/transparent'/(stem+'.png')
    if t.exists(): im=Image.open(t); name=stem+'.png'; im.save(IMG/name,optimize=True)
    else: im=Image.open(source).convert('RGB'); name=stem+'.jpg'; im.save(IMG/name,quality=82,optimize=True)
    w,h=im.size
    return f'<img src="/assets/img/{name}" alt="{html.escape(alt)}" width="{w}" height="{h}" '+('fetchpriority="high"' if eager else 'loading="lazy"')+'>'
def strip_image(path, alt):
    # Normalize the light studio backgrounds into transparent, ink-toned cutouts.
    from PIL import ImageFilter, ImageChops, ImageOps
    source=Image.open(ROOT/'reference/img/images'/path).convert('L')
    background=source.filter(ImageFilter.GaussianBlur(18))
    diff=ImageChops.subtract(background, source)
    alpha=diff.point(lambda x: max(0, min(255, (x-4)*5)))
    im=Image.new('RGBA', source.size, (38, 49, 60, 0)); im.putalpha(alpha)
    name='strip-'+path.replace('/','-').rsplit('.',1)[0]+'.png'
    im.save(IMG/name,optimize=True)
    return f'<img src="/assets/img/{name}" alt="{html.escape(alt)}" width="{im.width}" height="{im.height}" loading="lazy">'
def cards(visual=False):
    thumbnails={'material-handling':'mat1big.jpg','food-service':'foodfryb.jpg','medical':'medical/med3-b.jpg','displays':'displays/disp1-b.jpg','shelving-guards':'shelving/shelv-6b.jpg'}
    def card(slug, title):
        thumb = f'<span class="line-thumb">{strip_image(thumbnails[slug], "")}</span>' if visual and slug in thumbnails else ''
        return f'<a class="product-card" href="/products/{slug}/">{thumb}<span class="line-title">{title}</span><span class="line-arrow" aria-hidden="true">↗</span></a> '
    return ''.join(card(slug,title) for slug,(title,desc,photos) in sorted(PRODUCTS.items(), key=lambda item: not bool(item[1][2])))
def siblings(current):
    links=''.join(f'<li><a href="/products/{slug}/"'+(' aria-current="page"' if slug==current else '')+f'>{title}</a></li>' for slug,(title,desc,photos) in PRODUCTS.items())
    return f'<nav class="siblings" aria-label="Product lines"><div class="wrap"><ul>{links}</ul></div></nav>'
def band(): return '<section class="quote-band"><div class="wrap band-inner"><a class="button" href="/contact/#quote">Request a quote</a></div></section>'
